const campusVideo=document.querySelector('#campus-video');const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');if(reducedMotion.matches)campusVideo.pause();else campusVideo.play().catch(()=>{});reducedMotion.addEventListener('change',e=>{if(e.matches)campusVideo.pause()});document.querySelector('#watch-film').onclick=()=>{campusVideo.pause();show('A glimpse of life at SVS','<iframe src="https://drive.google.com/file/d/1c9aA98tMD-yLNcmo3dJ79rZTDowEAszM/preview" title="SVS college campus film" allow="autoplay; fullscreen" allowfullscreen></iframe><p>College film supplied for this presentation. <a href="https://drive.google.com/file/d/1c9aA98tMD-yLNcmo3dJ79rZTDowEAszM/view" target="_blank" rel="noopener">Open film in Google Drive ↗</a></p>','THE SVS CAMPUS FILM');dialog.classList.add('film-dialog')};dialog.addEventListener('close',()=>{if(dialog.classList.contains('film-dialog')){dialog.classList.remove('film-dialog');document.querySelector('#dialog-content').innerHTML=''}});
new IntersectionObserver(([entry])=>document.body.classList.toggle('hero-in-view',entry.isIntersecting),{threshold:0.15}).observe(document.querySelector('.hero-film'));
